const inputs = $input.all();
const postItems = $('Merge Prompts1').all();

const categorieMap = {
  'educatif': 'Educatif',
  'actualite': 'Actualite',
  'cas_concrets': 'Cas_Concrets',
  'mythbusters': 'Mythbusters',
  'chiffres_choc': 'Chiffres_Choc',
  'predictions': 'Predictions'
};

return inputs.map((input, index) => {
  const post = postItems[index]?.json || {};

  return {
    json: {
      titre_interne: post.titre_interne || '',
      categorie: categorieMap[post.categorie?.toLowerCase()] || post.categorie || '',
      hook: post.hook || '',
      corps: post.corps || '',
      cta: post.cta || '',
      hashtags: Array.isArray(post.hashtags) ? post.hashtags.join(' ') : (post.hashtags || ''),
      format_visuel: post.format_visuel || '',
      prompt_image: post.prompt_image || '',
      image_url: input.json.secure_url || '',
      score_ia: post.score_ia || 0,
      score_hook: post.score_hook || 0,
      score_commentaires: post.score_commentaires || 0,
      score_originalite: post.score_originalite || 0,
      score_valeur: post.score_valeur || 0,
      score_structure: post.score_structure || 0,
      points_forts: post.points_forts || '',
      suggestions_ia: post.suggestions_ia || '',
      statut: 'A_Valider',
      created_at: new Date().toISOString(),
      date_generation: new Date().toISOString()
    },
    pairedItem: { item: index }
  };
});

// === ACCUMULATEUR : attend les 6 flux RSS avant de traiter ===
const TOTAL_FEEDS = 6;
const STALE_TIMEOUT = 300000; // 5 min - reset si execution precedente a plante

const staticData = $getWorkflowStaticData('node');
const now = Date.now();

// Reset si donnees perimees (execution precedente echouee)
if (staticData.timestamp && (now - staticData.timestamp) > STALE_TIMEOUT) {
  staticData.rawItems = [];
  staticData.feedCount = 0;
}

// Initialiser
if (!staticData.rawItems) {
  staticData.rawItems = [];
  staticData.feedCount = 0;
}

// Accumuler les items de ce flux RSS
staticData.timestamp = now;
const newItems = $input.all().map(i => i.json);
staticData.rawItems = staticData.rawItems.concat(newItems);
staticData.feedCount++;

// Pas encore tous les flux ? Retourner vide (bloque la suite)
if (staticData.feedCount < TOTAL_FEEDS) {
  return [];
}

// === Tous les flux recus ! Traiter ===
const allItems = staticData.rawItems;

// Reset pour la prochaine execution
staticData.rawItems = [];
staticData.feedCount = 0;
staticData.timestamp = null;

function cleanText(text) {
  if (!text) return '';
  return text
    .replace(/<[^>]*>/g, '')
    .replace(/\s+/g, ' ')
    .trim()
    .substring(0, 1000);
}

const seen = new Set();
const cleaned = [];

for (const item of allItems) {
  const key = (item.title || item.text || item.content || '').substring(0, 100);
  if (key && !seen.has(key)) {
    seen.add(key);
    cleaned.push({
      source: item.source || item.companyName || 'RSS',
      title: cleanText(item.title || ''),
      content: cleanText(item.content || item.text || item.description || ''),
      engagement: item.likes || item.reactions || item.numLikes || 0,
      comments: item.comments || item.numComments || 0,
      date: item.pubDate || item.postedAt || item.date || new Date().toISOString(),
      url: item.link || item.url || item.postUrl || ''
    });
  }
}

const sorted = cleaned
  .sort((a, b) => (b.engagement + b.comments) - (a.engagement + a.comments))
  .slice(0, 40);

return [{ json: { veille_data: sorted, count: sorted.length } }];

let content = $input.first().json.message?.content || (Array.isArray($input.first().json.content) ? $input.first().json.content[0].text : $input.first().json.content);

if (typeof content === 'string') {
  content = content.replace(/```json\n?/g, '').replace(/```\n?/g, '');
  content = JSON.parse(content);
}

const posts = content.posts || content;

const enrichedPosts = posts.map((post, index) => {
  // Retirer le hook du début du corps s'il est dupliqué
  if (post.corps && post.hook && post.corps.trim().startsWith(post.hook.trim())) {
    post.corps = post.corps.trim().slice(post.hook.trim().length).trim();
  }

  return {
    ...post,
    date_generation: new Date().toISOString(),
    statut: 'A_Valider',
    score_ia: 0,
    suggestions_ia: ''
  };
});

return enrichedPosts.map(post => ({ json: post }));

const items = $input.all();
const parsedPosts = $('Parse Posts1').all();

return items.map((item, index) => {
  const post = parsedPosts[index]?.json || {};
  let scoreData = item.json.message?.content || (Array.isArray(item.json.content) ? item.json.content[0].text : item.json.content) || item.json;

  if (typeof scoreData === 'string') {
    scoreData = scoreData.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
    try {
      scoreData = JSON.parse(scoreData);
    } catch (e) {
      // JSON tronqué : extraire les scores avec regex
      const extract = (key) => {
        const match = scoreData.match(new RegExp(`"${key}"\\s*:\\s*([\\d.]+)`));
        return match ? parseFloat(match[1]) : 0;
      };
      scoreData = {
        score_hook: extract('score_hook'),
        score_commentaires: extract('score_commentaires'),
        score_originalite: extract('score_originalite'),
        score_valeur: extract('score_valeur'),
        score_structure: extract('score_structure'),
        score_final: extract('score_final'),
        points_forts: '',
        suggestions: ''
      };
      if (!scoreData.score_final) {
        const scores = [scoreData.score_hook, scoreData.score_commentaires, scoreData.score_originalite, scoreData.score_valeur, scoreData.score_structure].filter(s => s > 0);
        scoreData.score_final = scores.length ? (scores.reduce((a, b) => a + b, 0) / scores.length) : 7;
      }
    }
  }

  return {
    json: {
      ...post,
      score_ia: scoreData.score_final || 7,
      score_hook: scoreData.score_hook || 0,
      score_commentaires: scoreData.score_commentaires || 0,
      score_originalite: scoreData.score_originalite || 0,
      score_valeur: scoreData.score_valeur || 0,
      score_structure: scoreData.score_structure || 0,
      points_forts: scoreData.points_forts || '',
      suggestions_ia: scoreData.suggestions || ''
    }
  };
});

