const items = $input.all();
const mergedScores = $('Merge Score1').all();

return items.map((item, index) => {
  const post = mergedScores[index]?.json || {};
  let promptData = item.json.message?.content || (Array.isArray(item.json.content) ? item.json.content[0].text : item.json.content) || item.json;

  if (typeof promptData === 'string') {
    promptData = promptData.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
    promptData = JSON.parse(promptData);
  }

  return {
    json: {
      ...post,
      format_visuel: promptData.format_visuel || 'illustration',
      prompt_image: promptData.prompt_image || '',
      include_text: promptData.include_text || false,
      text_to_include: promptData.text_to_include || ''
    }
  };
});

const posts = $input.all();

// Si aucun post ou erreur Supabase, retourner un message par defaut
if (!posts || posts.length === 0 || !posts[0].json.id) {
  return [{ json: {
    anti_repetition: 'Aucun post recent en base. Libre choix des sujets et categories.',
    categories_recentes: []
  } }];
}

const summary = posts.map(p => {
  const j = p.json;
  return `- [${j.categorie || 'N/A'}] ${j.titre_interne || 'Sans titre'} | Hook: ${(j.hook || '').substring(0, 80)}`;
}).join('\n');

const categories = posts
  .map(p => p.json.categorie?.toLowerCase())
  .filter(Boolean);

const categoryCounts = {};
categories.forEach(c => { categoryCounts[c] = (categoryCounts[c] || 0) + 1; });

const categoryInfo = Object.entries(categoryCounts)
  .map(([cat, count]) => `${cat}: ${count} fois`)
  .join(', ');

return [{ json: {
  anti_repetition: `Voici les ${posts.length} derniers posts generes. NE REPETE PAS ces sujets, angles ou hooks.\n\nCategories utilisees recemment : ${categoryInfo}\n\nPosts recents :\n${summary}`,
  categories_recentes: categories
} }];
